REQUESTS = [
    {"user": "asha", "identity_verified": True, "device_compliant": True, "mfa": True, "resource_sensitivity": "high"},
    {"user": "ravi", "identity_verified": True, "device_compliant": False, "mfa": True, "resource_sensitivity": "low"},
    {"user": "kim", "identity_verified": True, "device_compliant": True, "mfa": False, "resource_sensitivity": "high"},
    {"user": "bot-ci", "identity_verified": False, "device_compliant": True, "mfa": False, "resource_sensitivity": "low"},
]

def evaluate(req):
    if not req['identity_verified']:
        return 'DENY (identity_not_verified)'
    if not req['device_compliant']:
        return 'DENY (device_not_compliant)'
    if req['resource_sensitivity'] == 'high' and not req['mfa']:
        return 'DENY (mfa_required)'
    return 'ALLOW'

allowed = 0
for req in REQUESTS:
    decision = evaluate(req)
    if decision == 'ALLOW':
        allowed += 1
    print(f"{req['user']} -> {decision}")
print(f"Allowed: {allowed}/{len(REQUESTS)}")
